/* Generated by tools/build_lines.py from picks/g18.txt. Every line is from: NCERT XII (old) Unit 7. Do not edit by hand. */
(function () {
  const R = window.RES;
  R.addLines("g18", "NCERT XII (old) Unit 7", [{"sec": "Occurrence","ids": [572,573,574],"t": "Group 18 (noble gases): He, Ne, Ar, Kr, Xe, Rn, Og; gases, very unreactive, few compounds.","exc": false,"tab": false,"src": "p15","page": 39,"o": "Group 18 consists of elements: helium, neon, argon, krypton, xenon, radon and oganesson. All these are gases and chemically unreactive. They form very few compounds, because of this they are termed as noble gases."},{"sec": "Occurrence","ids": [575,576],"t": "All except Rn and Og occur in the atmosphere (~1% of dry air, mostly Ar).","exc": false,"tab": false,"src": "p15","page": 39,"o": "All these gases except radon and oganesson occur in the atmosphere. Their atmospheric abundance in dry air is ~ 1% by volume of which argon is the major constituent."},{"sec": "Occurrence","ids": [577,578],"t": "He (sometimes Ne) in radioactive minerals (pitchblende, monazite, cleveite); main commercial He source: natural gas.","exc": false,"tab": false,"src": "p15","page": 39,"o": "Helium and sometimes neon are found in minerals of radioactive origin e.g., pitchblende, monazite, cleveite. The main commercial source of helium is natural gas."},{"sec": "Occurrence","ids": [579],"t": "Xe and Rn are the rarest.","exc": false,"tab": false,"src": "p15","page": 39,"o": "Xenon and radon are the rarest elements of the group."},{"sec": "Occurrence","ids": [580],"t": "Radon is obtained as a decay product of ^226Ra: ^226_88Ra → ^222_86Rn + ^4_2He","exc": false,"tab": true,"src": "p15","page": 39,"o": "Radon is obtained as a decay product of ^226Ra: ^226_88Ra → ^222_86Rn + ^4_2He"},{"sec": "Occurrence","ids": [580],"t": "Oganesson has been synthetically produced by collision of ^249_98Cf atoms and ^48_20Ca ions: ^249_98Cf + ^48_20Ca → ^294_118Og + 3n","exc": false,"tab": true,"src": "p15","page": 39,"o": "Oganesson has been synthetically produced by collision of ^249_98Cf atoms and ^48_20Ca ions: ^249_98Cf + ^48_20Ca → ^294_118Og + 3n"},{"sec": "Occurrence","ids": [581,582],"t": "Filled valence shells; react only with a few elements under special conditions.","exc": false,"tab": false,"src": "p15","page": 39,"o": "The elements present in Group 18 have their valence shell orbitals completely filled and, therefore, react with a few elements only under certain conditions. Therefore, they are now known as noble gases."},{"sec": "Occurrence","ids": [583,585],"t": "Og: Z = 118, [Rn] 5f^14 6d^10 7s^2 7p^6, t½ 0.7 ms.","exc": false,"tab": false,"src": "p15","page": 39,"o": "Oganesson has its symbol Og, atomic number 118, atomic mass 294 and electronic configuration [Rn] 5f^14 6d^10 7s^2 7p^6. Its half life is 0.7 milliseconds."},{"sec": "Atomic and physical properties","ids": [589],"t": "Table 7.12: Ionisation enthalpy/kJ mol^-1 He 2372, Ne 2080, Ar 1520, Kr 1351, Xe 1170, Rn 1037. Electron gain enthalpy/kJ mol^-1 He 48, Ne 116, Ar 96, Kr 96, Xe 77, Rn 68. Atomic radius/pm He 120, Ne 160, Ar 190, Kr 200, Xe 220.","exc": false,"tab": true,"src": "p15","page": 39,"o": "Table 7.12: Ionisation enthalpy/kJ mol^-1 He 2372, Ne 2080, Ar 1520, Kr 1351, Xe 1170, Rn 1037. Electron gain enthalpy/kJ mol^-1 He 48, Ne 116, Ar 96, Kr 96, Xe 77, Rn 68. Atomic radius/pm He 120, Ne 160, Ar 190, Kr 200, Xe 220."},{"sec": "Atomic and physical properties","ids": [590],"t": "ns^2np^6, **except He 1s^2**.","exc": true,"tab": false,"src": "p15","page": 40,"o": "All noble gases have general electronic configuration ns^2np^6 except helium which has 1s^2."},{"sec": "Atomic and physical properties","ids": [591],"t": "Inertness and other properties come from closed shells.","exc": false,"tab": false,"src": "p15","page": 40,"o": "Many of the properties of noble gases including their inactive nature are ascribed to their closed shell structures."},{"sec": "Atomic and physical properties","ids": [592,593],"t": "Very high ∆iH; decreases down the group.","exc": false,"tab": false,"src": "p15","page": 40,"o": "Due to stable electronic configuration these gases exhibit very high ionisation enthalpy. However, it decreases down the group with increase in atomic size."},{"sec": "Atomic and physical properties","ids": [594],"t": "Atomic radii increase down the group.","exc": false,"tab": false,"src": "p15","page": 40,"o": "Atomic radii increase down the group with increase in atomic number."},{"sec": "Atomic and physical properties","ids": [595],"t": "**Large positive ∆egH** (no tendency to accept electrons).","exc": false,"tab": false,"src": "p15","page": 40,"o": "Since noble gases have stable electronic configurations, they have no tendency to accept the electron and therefore, have large positive values of electron gain enthalpy."},{"sec": "Atomic and physical properties","ids": [596,597,598],"t": "Monoatomic; colourless, odourless, tasteless; sparingly soluble in water.","exc": false,"tab": false,"src": "p15","page": 40,"o": "All the noble gases are monoatomic. They are colourless, odourless and tasteless. They are sparingly soluble in water."},{"sec": "Atomic and physical properties","ids": [599],"t": "Very low m.p./b.p.: only weak dispersion forces.","exc": false,"tab": false,"src": "p15","page": 40,"o": "They have very low melting and boiling points because the only type of interatomic interaction in these elements is weak dispersion forces."},{"sec": "Atomic and physical properties","ids": [600],"t": "**He has the lowest b.p. of any substance (4.2 K).**","exc": true,"tab": false,"src": "p15","page": 40,"o": "Helium has the lowest boiling point (4.2 K) of any known substance."},{"sec": "Atomic and physical properties","ids": [601],"t": "He diffuses through rubber, glass, plastics.","exc": true,"tab": false,"src": "p15","page": 40,"o": "It has an unusual property of diffusing through most commonly used laboratory materials such as rubber, glass or plastics."},{"sec": "Chemical properties","ids": [601,602,603],"t": "Least reactive because (i) filled ns^2np^6 (He 1s^2), (ii) high ∆iH and positive ∆egH.","exc": false,"tab": false,"src": "p15","page": 40,"o": "In general, noble gases are least reactive. Their inertness to chemical reactivity is attributed to the following reasons: (i) The noble gases except helium (1s^2) have completely filled ns^2np^6 electronic configuration in their valence shell. (ii) They have high ionisation enthalpy and more positive electron gain enthalpy."},{"sec": "Chemical properties","ids": [605,606],"t": "First noble-gas reaction: O2 + PtF6 gave red O2^+PtF6^–.","exc": false,"tab": false,"src": "p15","page": 40,"o": "In March 1962, Neil Bartlett, then at the University of British Columbia, observed the reaction of a noble gas. First, he prepared a red compound which is formulated as O2^+PtF6^–."},{"sec": "Chemical properties","ids": [607],"t": "∆iH1 of O2 (1175 kJ mol^–1) ≈ Xe (1170 kJ mol^–1).","exc": false,"tab": false,"src": "p15","page": 40,"o": "He, then realised that the first ionisation enthalpy of molecular oxygen (1175 kJ mol^–1) was almost identical with that of xenon (1170 kJ mol^–1)."},{"sec": "Chemical properties","ids": [608],"t": "So Xe + PtF6 → red Xe^+PtF6^–.","exc": false,"tab": false,"src": "p15","page": 40,"o": "He made efforts to prepare same type of compound with Xe and was successful in preparing another red colour compound Xe^+PtF6^– by mixing PtF6 and xenon."},{"sec": "Chemical properties","ids": [609],"t": "Many Xe compounds followed, mostly with F and O.","exc": false,"tab": false,"src": "p15","page": 40,"o": "After this discovery, a number of xenon compounds mainly with most electronegative elements like fluorine and oxygen, have been synthesised."},{"sec": "Chemical properties","ids": [610,611],"t": "Kr: few compounds; only KrF2 studied in detail.","exc": false,"tab": false,"src": "p15","page": 40,"o": "The compounds of krypton are fewer. Only the difluoride (KrF2) has been studied in detail."},{"sec": "Chemical properties","ids": [612,616],"t": "**Rn compounds only identified (e.g. RnF2) by radiotracer, not isolated.**","exc": true,"tab": false,"src": "p15","page": 40,"o": "Compounds of radon have not been isolated but only identified (e.g., RnF2) by radiotracer technique."},{"sec": "Chemical properties","ids": [614,615],"t": "Monoatomic, only dispersion forces, so liquefied only at very low T.","exc": false,"tab": false,"src": "p15","page": 40,"o": "Noble gases being monoatomic have no interatomic forces except weak dispersion forces and therefore, they are liquefied at very low temperatures. Hence, they have low boiling points. 2020-21"},{"sec": "Chemical properties","ids": [617],"t": "**No true compounds of Ar, Ne or He.**","exc": true,"tab": false,"src": "p15","page": 41,"o": "No true compounds of Ar, Ne or He are yet known."},{"sec": "Chemical properties","ids": [704],"t": "Rn is radioactive with a very short half-life, which hampers its study.","exc": false,"tab": false,"src": "p15","page": 45,"o": "Radon is radioactive with very short half-life which makes the study of chemistry of radon difficult."},{"sec": "Xenon fluorides","ids": [618],"t": "Xe forms XeF2, XeF4, XeF6 by direct reaction.","exc": false,"tab": false,"src": "p15","page": 41,"o": "Xenon forms three binary fluorides, XeF2, XeF4 and XeF6 by the direct reaction of elements under appropriate experimental conditions."},{"sec": "Xenon fluorides","ids": [619],"t": "Xe(g) + F2(g) → XeF2(s) (673 K, 1 bar; xenon in excess)","exc": false,"tab": true,"src": "p15","page": 41,"o": "Xe(g) + F2(g) → XeF2(s) (673 K, 1 bar; xenon in excess)"},{"sec": "Xenon fluorides","ids": [619],"t": "Xe(g) + 2F2(g) → XeF4(s) (873 K, 7 bar; 1:5 ratio)","exc": false,"tab": true,"src": "p15","page": 41,"o": "Xe(g) + 2F2(g) → XeF4(s) (873 K, 7 bar; 1:5 ratio)"},{"sec": "Xenon fluorides","ids": [619],"t": "Xe(g) + 3F2(g) → XeF6(s) (573 K, 60-70 bar; 1:20 ratio)","exc": false,"tab": true,"src": "p15","page": 41,"o": "Xe(g) + 3F2(g) → XeF6(s) (573 K, 60-70 bar; 1:20 ratio)"},{"sec": "Xenon fluorides","ids": [619],"t": "XeF4 + O2F2 → XeF6 + O2 (143 K)","exc": false,"tab": false,"src": "p15","page": 41,"o": "XeF6 can also be prepared by the interaction of XeF4 and O2F2 at 143K. XeF4 + O2F2 → XeF6 + O2"},{"sec": "Xenon fluorides","ids": [619],"t": "Xe fluorides: colourless crystalline solids, sublime readily at 298 K; powerful fluorinating agents.","exc": false,"tab": false,"src": "p15","page": 41,"o": "XeF2, XeF4 and XeF6 are colourless crystalline solids and sublime readily at 298 K. They are powerful fluorinating agents."},{"sec": "Xenon fluorides","ids": [620,621],"t": "Hydrolysed even by traces of water: 2XeF2 + 2H2O → 2Xe + 4HF + O2","exc": false,"tab": false,"src": "p15","page": 41,"o": "They are readily hydrolysed even by traces of water. For example, XeF2 is hydrolysed to give Xe, HF and O2. 2XeF2(s) + 2H2O(l) → 2Xe(g) + 4HF(aq) + O2(g)"},{"sec": "Xenon fluorides","ids": [621,622],"t": "**XeF2 linear, XeF4 square planar** (VSEPR).","exc": false,"tab": false,"src": "p15","page": 41,"o": "The structures of the three xenon fluorides can be deduced from VSEPR. XeF2 and XeF4 have linear and square planar structures respectively."},{"sec": "Xenon fluorides","ids": [623],"t": "**XeF6: 6 bp + 1 lp, distorted octahedral** (gas phase).","exc": true,"tab": false,"src": "p15","page": 41,"o": "XeF6 has seven electron pairs (6 bonding pairs and one lone pair) and would, thus, have a distorted octahedral structure as found experimentally in the gas phase."},{"sec": "Xenon fluorides","ids": [624],"t": "With F^– acceptors they form cations; with F^– donors, fluoroanions.","exc": false,"tab": false,"src": "p15","page": 41,"o": "Xenon fluorides react with fluoride ion acceptors to form cationic species and fluoride ion donors to form fluoroanions."},{"sec": "Xenon fluorides","ids": [625],"t": "XeF2 + PF5 → [XeF]^+[PF6]^–; XeF4 + SbF5 → [XeF3]^+[SbF6]^–; XeF6 + MF → M^+[XeF7]^– (M = Na, K, Rb or Cs)","exc": false,"tab": false,"src": "p15","page": 41,"o": "XeF2 + PF5 → [XeF]^+[PF6]^–; XeF4 + SbF5 → [XeF3]^+[SbF6]^–; XeF6 + MF → M^+[XeF7]^– (M = Na, K, Rb or Cs)"},{"sec": "Xenon-oxygen compounds","ids": [616],"t": "Fig. 7.9: (a) XeF2 linear (b) XeF4 square planar (c) XeF6 distorted octahedral (d) XeOF4 square pyramidal (e) XeO3 pyramidal.","exc": false,"tab": true,"src": "p15","page": 41,"o": "Fig. 7.9: (a) XeF2 linear (b) XeF4 square planar (c) XeF6 distorted octahedral (d) XeOF4 square pyramidal (e) XeO3 pyramidal."},{"sec": "Xenon-oxygen compounds","ids": [625],"t": "XeO3 from hydrolysis: 6XeF4 + 12H2O → 4Xe + 2XeO3 + 24HF + 3O2; XeF6 + 3H2O → XeO3 + 6HF","exc": false,"tab": false,"src": "p15","page": 41,"o": "Hydrolysis of XeF4 and XeF6 with water gives XeO3. 6XeF4 + 12H2O → 4Xe + 2XeO3 + 24HF + 3O2; XeF6 + 3H2O → XeO3 + 6HF"},{"sec": "Xenon-oxygen compounds","ids": [625,626],"t": "Partial hydrolysis of XeF6: XeF6 + H2O → XeOF4 + 2HF; XeF6 + 2H2O → XeO2F2 + 4HF","exc": false,"tab": false,"src": "p15","page": 41,"o": "Partial hydrolysis of XeF6 gives oxyfluorides, XeOF4 and XeO2F2. XeF6 + H2O → XeOF4 + 2HF; XeF6 + 2H2O → XeO2F2 + 4HF"},{"sec": "Xenon-oxygen compounds","ids": [627],"t": "**XeO3: colourless explosive solid, pyramidal.**","exc": false,"tab": false,"src": "p15","page": 42,"o": "XeO3 is a colourless explosive solid and has a pyramidal molecular structure."},{"sec": "Xenon-oxygen compounds","ids": [628],"t": "**XeOF4: colourless volatile liquid, square pyramidal.**","exc": false,"tab": false,"src": "p15","page": 42,"o": "XeOF4 is a colourless volatile liquid and has a square pyramidal molecular structure."},{"sec": "Xenon-oxygen compounds","ids": [630],"t": "Partial hydrolysis of XeF6 is **not a redox reaction** (oxidation states unchanged).","exc": true,"tab": false,"src": "p15","page": 42,"o": "No, the products of hydrolysis are XeOF4 and XeO2F2 where the oxidation states of all the elements remain the same as it was in the reacting state."},{"sec": "Uses","ids": [631,632,633],"t": "He: non-inflammable, light; weather balloons; gas-cooled nuclear reactors.","exc": false,"tab": false,"src": "p15","page": 42,"o": "Helium is a non-inflammable and light gas. Hence, it is used in filling balloons for meteorological observations. It is also used in gas-cooled nuclear reactors."},{"sec": "Uses","ids": [634],"t": "Liquid He (4.2 K): cryogenic agent.","exc": false,"tab": false,"src": "p15","page": 42,"o": "Liquid helium (b.p. 4.2 K) finds use as cryogenic agent for carrying out various experiments at low temperatures."},{"sec": "Uses","ids": [635],"t": "He: superconducting magnets for NMR and MRI.","exc": false,"tab": false,"src": "p15","page": 42,"o": "It is used to produce and sustain powerful superconducting magnets which form an essential part of modern NMR spectrometers and Magnetic Resonance Imaging (MRI) systems for clinical diagnosis."},{"sec": "Uses","ids": [636],"t": "He dilutes O2 in diving apparatus (very low solubility in blood).","exc": false,"tab": false,"src": "p15","page": 42,"o": "It is used as a diluent for oxygen in modern diving apparatus because of its very low solubility in blood."},{"sec": "Uses","ids": [637,638],"t": "Ne: discharge tubes, fluorescent advertising bulbs; neon bulbs in botanical gardens, greenhouses.","exc": false,"tab": false,"src": "p15","page": 42,"o": "Neon is used in discharge tubes and fluorescent bulbs for advertisement display purposes. Neon bulbs are used in botanical gardens and in green houses."},{"sec": "Uses","ids": [639],"t": "Ar: inert atmosphere for high-T metallurgy (arc welding); filling bulbs.","exc": false,"tab": false,"src": "p15","page": 42,"o": "Argon is used mainly to provide an inert atmosphere in high temperature metallurgical processes (arc welding of metals or alloys) and for filling electric bulbs."},{"sec": "Uses","ids": [640],"t": "Ar: handling air-sensitive substances.","exc": false,"tab": false,"src": "p15","page": 42,"o": "It is also used in the laboratory for handling substances that are air-sensitive."},{"sec": "Uses","ids": [641,642],"t": "Xe, Kr: special-purpose light bulbs only.","exc": false,"tab": false,"src": "p15","page": 42,"o": "There are no significant uses of Xenon and Krypton. They are used in light bulbs designed for special purposes."}]);
})();
